sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var buddyNameField = 'u_buddy_name'; // Replace with your Buddy field backend name

    if (!newValue) {
        g_form.clearValue(buddyNameField);
        return;
    }

    var ga = new GlideAjax('TripRequestBuddiesNameUtils');
    ga.addParam('sysparm_name', 'getBuddyInfo');
    ga.addParam('sysparm_trip_id', newValue);
    ga.getXMLAnswer(function(response) {
        if (response) {
            var data = JSON.parse(response);
            if (data.sys_id) {
                // Passes sys_id AND display name so the Reference field renders properly
                g_form.setValue(buddyNameField, data.sys_id, data.name);
            }
        }
    });
}
